"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[2623],{1174(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>d,default:()=>h,frontMatter:()=>l,metadata:()=>i,toc:()=>u});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/intake-package","title":"What Arrives on the Lead AI Engineer\u2019s Desk (Enterprise Intake Package)","description":"This HTML tutorial is designed for future Lead AI Engineers in large enterprises (banks/airlines). It describes the typical \u201cpackage\u201d you receive when a business use case is ready to become a real AI delivery. The goa...","source":"@site/docs/part1-enterprise-ai-delivery/02-intake-package.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/02-intake-package","permalink":"/tutorials/part1-enterprise-ai-delivery/02-intake-package","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":2,"frontMatter":{"title":"What Arrives on the Lead AI Engineer\u2019s Desk (Enterprise Intake Package)","slug":"/part1-enterprise-ai-delivery/02-intake-package","description":"This HTML tutorial is designed for future Lead AI Engineers in large enterprises (banks/airlines). It describes the typical \u201cpackage\u201d you receive when a business use case is ready to become a real AI delivery. The goa...","sidebar_label":"2. The intake package","pagination_label":"2. The intake package","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"1. From business pain to AI lead","permalink":"/tutorials/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead"},"next":{"title":"3. AI lead response document","permalink":"/tutorials/part1-enterprise-ai-delivery/03-ai-lead-response"}}');var s=t(4848),a=t(8453),r=t(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/02-intake-package.html","route":"/part1-enterprise-ai-delivery/02-intake-package","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"Enterprise Intake Package: What Arrives on the Lead AI Engineer\u2019s Desk","title":"What Arrives on the Lead AI Engineer\u2019s Desk (Enterprise Intake Package)","description":"This HTML tutorial is designed for future Lead AI Engineers in large enterprises (banks/airlines). It describes the typical \u201cpackage\u201d you receive when a business use case is ready to become a real AI delivery. The goa...","readingMinutes":4,"bodyClass":"","normalizeMath":false,"toc":[{"id":"why","label":"1) Why an \u201cintake package\u201d exists"},{"id":"what","label":"2) What you should receive (the \u201cminimum viable intake\u201d)"},{"id":"roles","label":"3) Who the people are (and what you should expect from them)"},{"id":"redflags","label":"4) Red flags (signals the intake is not ready)"},{"id":"day1","label":"5) What you do on day 1 (as Lead AI Engineer)"},{"id":"template","label":"6) Copy/paste template: \u201cWhat I expect to receive\u201d"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This HTML tutorial is designed for <strong>future Lead AI Engineers</strong> in large enterprises (banks/airlines).\\n      It describes the typical \u201cpackage\u201d you receive when a business use case is ready to become a real AI delivery.\\n      The goal is to help you quickly assess readiness, risks, and your day-1 actions.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#why\\">Why this package exists</a></li>\\n      <li><a href=\\"#what\\">What you should receive</a></li>\\n      <li><a href=\\"#roles\\">Who the people are</a></li>\\n      <li><a href=\\"#redflags\\">Red flags &amp; missing pieces</a></li>\\n      <li><a href=\\"#day1\\">What you do on day 1</a></li>\\n      <li><a href=\\"#template\\">Copy/paste intake template</a></li>\\n    </ul>\\n\\n    <h2 id=\\"why\\">1) Why an \u201cintake package\u201d exists</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        In an enterprise, \u201cAI requests\u201d are filtered through governance (security/privacy/risk/architecture) so delivery teams\\n        don\u2019t start with a vague idea. When the request reaches you, it should already have:\\n      </p>\\n      <ul>\\n        <li>a defined business problem</li>\\n        <li>an owner accountable for outcomes</li>\\n        <li>approved or approvable data sources</li>\\n        <li>constraints (privacy/security/audit) made explicit</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>Lead-level expectation:</strong> you convert the package into scope, architecture, evaluation gates,\\n        operating model, and a pilot plan \u2014 not \u201cbuild a demo.\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"what\\">2) What you should receive (the \u201cminimum viable intake\u201d)</h2>\\n\\n    <div class=\\"ok\\">\\n      <strong>If you don\u2019t receive these, ask for them immediately.</strong>\\n      You can still proceed in discovery mode, but you should treat it as \u201cnot ready for build.\u201d\\n    </div>\\n\\n    <div class=\\"checklist\\">\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Business brief</div>\\n        <ul>\\n          <li>problem statement (\u201cwhat hurts\u201d)</li>\\n          <li>users + workflow (who does what today)</li>\\n          <li>example questions/tasks</li>\\n          <li>success metrics (time saved, accuracy, adoption)</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Ownership</div>\\n        <ul>\\n          <li><strong>Sponsor</strong> (senior leader who backs it)</li>\\n          <li><strong>Business owner</strong> (accountable for outcomes + adoption)</li>\\n          <li>named representatives: EA + Ops + SME</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Data scope</div>\\n        <ul>\\n          <li>which sources (Drive/SharePoint/Confluence/email/transcripts)</li>\\n          <li>who the <strong>data owner</strong> is for each source</li>\\n          <li>what is in-scope vs out-of-scope</li>\\n          <li>data sensitivity classification (PII/confidential/etc.)</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Constraints &amp; controls</div>\\n        <ul>\\n          <li>access control expectations (\u201cwho can see what\u201d)</li>\\n          <li>audit/logging requirements</li>\\n          <li>privacy requirements (PII handling, retention)</li>\\n          <li>risk tolerance: \u201cwhat happens if it\u2019s wrong?\u201d</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Delivery expectations</div>\\n        <ul>\\n          <li>pilot cohort size and timeline</li>\\n          <li>support model (who owns it after launch)</li>\\n          <li>non-functional requirements: latency, uptime</li>\\n        </ul>\\n      </div>\\n\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Approvals / gates</div>\\n        <ul>\\n          <li>security/IAM contact for approvals</li>\\n          <li>privacy/legal/risk contact if needed</li>\\n          <li>architecture review process (if required)</li>\\n        </ul>\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"roles\\">3) Who the people are (and what you should expect from them)</h2>\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Role</th>\\n          <th>What they provide in the intake</th>\\n          <th>What you should ask them</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>Sponsor</strong> (often GM-level)</td>\\n          <td>Authority, budget influence, unblock access issues, approve pilot scope</td>\\n          <td>\u201cWhat\u2019s the business outcome, and how will we measure success?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Business owner</strong></td>\\n          <td>Accountability for adoption, priorities, and acceptance criteria</td>\\n          <td>\u201cWhich workflows are must-have for pilot? What is the rollout plan?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>EA (Executive Assistant)</strong></td>\\n          <td>Real workflow + top recurring exec questions + acceptable answer format</td>\\n          <td>\u201cWhat does \u2018proof\u2019 look like? Link/snippet/timestamp? What\u2019s the top 20 questions?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Ops (Operations)</strong></td>\\n          <td>Urgency constraints + failure tolerance + what \u201cwrong answer\u201d costs</td>\\n          <td>\u201cWhen it\u2019s wrong, what\u2019s the impact? When it\u2019s missing, how should it behave?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>SME (Subject Matter Expert)</strong></td>\\n          <td>Ground truth interpretations + what docs matter + evaluation support</td>\\n          <td>\u201cWhat sources are authoritative? What are common ambiguous cases?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Data owner</strong></td>\\n          <td>Approval for access, usage, retention, classification rules</td>\\n          <td>\u201cWhat is allowed to be ingested? Any exclusions? How should retention work?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Security/IAM</strong></td>\\n          <td>Access model constraints, least privilege guidance, secrets/network expectations</td>\\n          <td>\u201cWhat\u2019s the approved pattern for identity, service accounts, and audit logging?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Privacy/Legal/Risk</strong></td>\\n          <td>PII/regulated-data constraints, release conditions, policy compliance</td>\\n          <td>\u201cWhat data can leave the boundary? What redaction/logging rules apply?\u201d</td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>EM (Engineering Manager)</strong></td>\\n          <td>Resourcing, delivery cadence, quality bar, operational ownership</td>\\n          <td>\u201cWhat\u2019s the team capacity and what must we trade off to hit pilot?\u201d</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <div class=\\"callout\\">\\n      <strong>Quick reminder:</strong>\\n      \u201cEA\u201d and \u201cOps\u201d are not merely \u201cstakeholders.\u201d They often define the workflow reality and the acceptable output format.\\n      If you skip them, you risk building something that demos well but doesn\u2019t get used.\\n    </div>\\n\\n    <h2 id=\\"redflags\\">4) Red flags (signals the intake is not ready)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>No business owner:</strong> nobody accountable for adoption \u2192 high risk of \u201cdemo only.\u201d</li>\\n        <li><strong>No data owner identified:</strong> access will stall later.</li>\\n        <li><strong>Unbounded scope:</strong> \u201csearch all documents in the company\u201d on day 1 \u2192 push back to a pilot corpus.</li>\\n        <li><strong>No success metric:</strong> you can\u2019t prove impact \u2192 define baseline and targets.</li>\\n        <li><strong>No risk statement:</strong> \u201cwrong answers are fine\u201d is rarely true in enterprise.</li>\\n        <li><strong>No access model:</strong> unclear whether users have different document permissions.</li>\\n      </ul>\\n\\n      <div class=\\"warn\\">\\n        <strong>Hard stop pattern:</strong> If they want \u201cfree-form Q&amp;A over everything\u201d without citations, auditing, or access control,\\n        you should reframe to a safe pilot first.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"day1\\">5) What you do on day 1 (as Lead AI Engineer)</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"your-day-1-goal\\">Your day-1 goal</h3>\\n      <p>\\n        Turn the intake package into a delivery-ready plan with measurable outcomes and safety controls.\\n      </p>\\n\\n      <h3 id=\\"day-1-outputs-typical\\">Day-1 outputs (typical)</h3>\\n      <ol>\\n        <li><strong>Problem reframing</strong> into a single sentence that implies controls (e.g., \u201ccited answers over approved corpus\u201d).</li>\\n        <li><strong>MVP definition</strong>: one BU, one corpus, 1\u20132 question patterns.</li>\\n        <li><strong>Evaluation plan</strong>: a golden set of 30\u201350 questions + citation correctness rubric.</li>\\n        <li><strong>Risk register</strong>: cross-user leakage, hallucinations, sensitive data exposure, adoption failure.</li>\\n        <li><strong>Architecture sketch</strong>: ingestion \u2192 canonical store \u2192 retrieval \u2192 LLM \u2192 citations \u2192 audit log.</li>\\n        <li><strong>Team plan</strong>: lanes (ingestion, backend/security, retrieval/LLM/eval) + owners + sprint goals.</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Lead-level move:</strong> schedule a co-design session with EAs and Ops within week 1.\\n        Ask them for the top recurring questions and define \u201cacceptable evidence.\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"template\\">6) Copy/paste template: \u201cWhat I expect to receive\u201d</h2>\\n    <div class=\\"card\\">\\n      <p class=\\"small\\">\\n        You can copy/paste this into an email/Confluence page and use it as your standard intake checklist.\\n      </p>\\n\\n      <h3 id=\\"6-1-intake-summary\\">6.1 Intake summary</h3>\\n      <ul>\\n        <li><strong>Problem statement:</strong> \u2026</li>\\n        <li><strong>BU / business area:</strong> \u2026</li>\\n        <li><strong>Users:</strong> \u2026</li>\\n        <li><strong>Top 5 user questions/tasks:</strong> \u2026</li>\\n      </ul>\\n\\n      <h3 id=\\"6-2-ownership\\">6.2 Ownership</h3>\\n      <ul>\\n        <li><strong>Sponsor:</strong> \u2026</li>\\n        <li><strong>Business owner:</strong> \u2026</li>\\n        <li><strong>EA representative:</strong> \u2026</li>\\n        <li><strong>Ops representative:</strong> \u2026</li>\\n        <li><strong>SME:</strong> \u2026</li>\\n      </ul>\\n\\n      <h3 id=\\"6-3-data-scope\\">6.3 Data scope</h3>\\n      <ul>\\n        <li><strong>Sources:</strong> \u2026</li>\\n        <li><strong>Data owners:</strong> \u2026</li>\\n        <li><strong>Classification:</strong> \u2026</li>\\n        <li><strong>Out of scope:</strong> \u2026</li>\\n      </ul>\\n\\n      <h3 id=\\"6-4-constraints-and-controls\\">6.4 Constraints &amp; controls</h3>\\n      <ul>\\n        <li><strong>Access control model:</strong> \u2026</li>\\n        <li><strong>Audit/logging requirements:</strong> \u2026</li>\\n        <li><strong>Privacy requirements (PII):</strong> \u2026</li>\\n        <li><strong>Failure tolerance:</strong> \u2026</li>\\n      </ul>\\n\\n      <h3 id=\\"6-5-success-criteria\\">6.5 Success criteria</h3>\\n      <ul>\\n        <li><strong>Business metrics:</strong> \u2026</li>\\n        <li><strong>Quality metrics:</strong> \u2026</li>\\n        <li><strong>Operational metrics:</strong> \u2026</li>\\n      </ul>\\n\\n      <h3 id=\\"6-6-delivery-expectations\\">6.6 Delivery expectations</h3>\\n      <ul>\\n        <li><strong>Pilot cohort:</strong> \u2026</li>\\n        <li><strong>Timeline:</strong> \u2026</li>\\n        <li><strong>Support model:</strong> \u2026</li>\\n        <li><strong>Approvals needed:</strong> \u2026</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>Rule of thumb:</strong>\\n        If you can\u2019t fill these fields, you\u2019re still in discovery, not delivery.\\n      </div>\\n    </div>\\n\\n    <p class=\\"footer-note\\">\\n      Want a realistic example filled out (meeting notes Q&amp;A for execs)?\\n      Tell me whether the documents are in Drive, SharePoint, Confluence, email, or transcripts and I\u2019ll generate a completed intake package.\\n    </p>\\n  </div>"}'),l={title:"What Arrives on the Lead AI Engineer\u2019s Desk (Enterprise Intake Package)",slug:"/part1-enterprise-ai-delivery/02-intake-package",description:"This HTML tutorial is designed for future Lead AI Engineers in large enterprises (banks/airlines). It describes the typical \u201cpackage\u201d you receive when a business use case is ready to become a real AI delivery. The goa...",sidebar_label:"2. The intake package",pagination_label:"2. The intake package",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},u=[];function p(e){return(0,s.jsx)(r.A,{content:o})}function h(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(p,{...e})}):p()}}}]);